BMH.field = (label,path,{type='number',min=0,max=9999999999,step=1,scale=1,options=null,hint='',prefix='',suffix=''}={}) => {
  const value=BMH.get(path);
  return `<label class="field"><span>${label}</span><div class="field-control">${prefix?`<i>${prefix}</i>`:''}${options?`<select data-path="${path}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,n=Array.isArray(o)?o[1]:o;return `<option value="${BMH.esc(v)}" ${String(value)===String(v)?'selected':''}>${BMH.esc(n)}</option>`}).join('')}</select>`:`<input data-path="${path}" data-scale="${scale}" type="${type}" min="${min}" max="${max}" step="${step}" value="${type==='number'?Number(value)/scale:BMH.esc(value)}">`}${suffix?`<em>${suffix}</em>`:''}</div>${hint?`<small>${hint}</small>`:''}</label>`;
};
BMH.hero = (step,title,accent,desc,{quote='',banner=true}={}) => `<section class="step-hero step-hero-${step} ${banner?'with-banner':'plain'}"><div class="hero-copy"><span class="eyebrow">BƯỚC ${step} TRONG 10</span><h1>${title} ${accent?`<em>${accent}</em>`:''}</h1><p>${desc}</p></div>${banner?`<div class="hero-art hero-clean"><img src="assets/design/hero-step1.jpg" alt="Nhà hiện đại"><div class="hero-fade"></div>${quote?`<blockquote>“${quote}”</blockquote>`:''}</div>`:''}</section>`;
BMH.cardTitle = (title,desc='') => `<div class="card-title"><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
BMH.sectionIcon = (char,title,desc='') => `<div class="section-heading"><i>${char}</i><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`;

BMH.compass = () => {
  const feng=BMH.fengProfile();
  const dirs=feng?.dirs||[];
  const good=new Set(dirs);
  const marks=[['Bắc',95,24],['Đông Bắc',153,45],['Đông',174,101],['Đông Nam',151,158],['Nam',95,180],['Tây Nam',38,158],['Tây',17,101],['Tây Bắc',39,45]];
  const labels=marks.map(([name,x,y])=>`<g class="compass-dir ${good.has(name)?'good':''}"><circle cx="${x}" cy="${y}" r="15"></circle><text x="${x}" y="${y+3}" text-anchor="middle">${name.replace('Đông ','Đ.').replace('Tây ','T.')}</text></g>`).join('');
  const owner=feng?.owner, partner=feng?.partner;
  return `<div class="official-compass"><svg viewBox="0 0 190 205" role="img" aria-label="La bàn Bát Trạch tham khảo"><circle cx="95" cy="102" r="70" class="compass-ring"></circle><circle cx="95" cy="102" r="48" class="compass-ring inner"></circle><line x1="95" y1="32" x2="95" y2="172"></line><line x1="25" y1="102" x2="165" y2="102"></line><line x1="45" y1="52" x2="145" y2="152"></line><line x1="145" y1="52" x2="45" y2="152"></line><polygon class="needle-n" points="95,45 86,105 95,97 104,105"></polygon><polygon class="needle-s" points="95,159 86,99 95,107 104,99"></polygon><circle class="hub" cx="95" cy="102" r="6"></circle>${labels}<text x="95" y="10" text-anchor="middle" class="compass-title">BÁT TRẠCH THAM KHẢO</text></svg><div class="dir-list"><strong>${BMH.esc(feng?.title||'Cung mệnh')}</strong><span class="feng-owners">${owner?`Gia chủ ${owner.number} · ${owner.group}`:'Chưa có dữ liệu gia chủ'}${partner?` · Đồng hành ${partner.number} · ${partner.group}`:''}</span>${dirs.map((d,i)=>`<em><span>${feng?.labels?.[i]||'Hướng tốt'}</span><b>${d}</b></em>`).join('')}<small>${BMH.esc(feng?.note||'Ưu tiên công năng, thông gió, ánh sáng và quy chuẩn xây dựng trước; phong thủy chỉ dùng như lớp tham khảo.')}</small></div></div>`;
};

BMH.screen1 = () => `<section class="official-start-hero"><div class="official-start-copy"><span class="eyebrow">BƯỚC 1 TRONG 10</span><h1>Khởi tạo <em>dự án mới</em></h1><p>Hãy cho chúng tôi biết bạn đã có những gì trước khi xây nhà.<br>Chọn một trong các luồng dưới đây để bắt đầu hành trình kiến tạo tổ ấm của bạn.</p></div><div class="official-start-art hero-clean"><img src="assets/design/hero-step1.jpg" alt="Ngôi nhà mơ ước"><blockquote>“Mọi hành trình lớn<br>đều bắt đầu từ một bước nhỏ.”</blockquote><small>Ngôi nhà mơ ước<br>bắt đầu từ hôm nay</small></div></section>
<div class="official-flow-grid">
  <article class="official-flow flow-a"><div class="flow-visual"><img src="assets/design/flow-a.jpg" alt="Ảnh nhà mẫu"><span>Luồng A</span></div><div class="flow-body"><h2>Tôi đã có ảnh nhà mẫu ưng ý</h2><p>Bạn có thể tải lên ảnh nhà mẫu tìm thấy trên mạng hoặc ảnh chụp thực tế. Những hình ảnh này sẽ được dùng làm tham khảo phong cách cho bước thiết kế.</p><button class="clay" data-start="photo">${BMH.icon('upload')} Tải ảnh lên <b>→</b></button><small>Hỗ trợ JPG, PNG · tối đa 10 ảnh</small></div></article>
  <article class="official-flow flow-b"><div class="flow-visual"><img src="assets/design/flow-b.jpg" alt="Bản vẽ"><span>Luồng B</span></div><div class="flow-body"><h2>Tôi đã có file bản vẽ (ảnh / PDF)</h2><p>Hệ thống ghi nhận bản vẽ làm tài liệu đối chiếu diện tích, số phòng và cấu trúc mặt bằng; bạn vẫn có thể chỉnh sửa phương án ở Bước 5.</p><button class="clay" data-start="plan">${BMH.icon('upload')} Tải bản vẽ <b>→</b></button><small>Hỗ trợ PDF, JPG, PNG · tối đa 20MB</small></div></article>
  <article class="official-flow flow-c"><div class="flow-visual"><img src="assets/design/flow-c.jpg" alt="Tư vấn từ đầu"><span>Luồng C</span></div><div class="flow-body"><h2>Tôi chưa có gì cả, cần gợi ý từ đầu</h2><p>Hệ thống sẽ đồng hành từ ngân sách, khu đất, thành viên gia đình đến vật liệu, dự toán và phương án mặt bằng sơ bộ.</p><button class="clay" data-start="suggest">Bắt đầu tư vấn ${BMH.icon('arrow')}</button><small>Phù hợp với gia đình mới bắt đầu lập kế hoạch</small></div></article>
</div>
<section class="official-benefits"><h2>Bạn sẽ nhận được gì?</h2><div><article><i>▤</i><b>Kế hoạch rõ ràng</b><span>Lộ trình 10 bước minh bạch, dễ theo dõi</span></article><article><i>◉</i><b>Kiểm soát chi phí</b><span>Dự toán thay đổi theo lựa chọn thực tế</span></article><article><i>⌂</i><b>Hỗ trợ chuyên môn</b><span>Mặt bằng và dữ liệu đủ để trao đổi với KTS</span></article><article><i>◇</i><b>Hài hòa gia đình</b><span>Công năng, khả năng tiếp cận và phong thủy tham khảo</span></article></div></section>`;

BMH.screen2 = () => {const f=BMH.state.project.finance,s=BMH.financeSummary(),bank=BMH.BANKS.find(b=>b.id===f.bank); const stress=[1,2,3].map(x=>{const payment=BMH.monthlyPayment(f.loan,f.postRate+x,f.years*12-f.promoMonths);return `<div><small>+${x}%</small><b>${BMH.money(payment)}</b><span>${Math.round((payment+f.existingDebt)/f.income*100)}% thu nhập</span></div>`}).join('');return `${BMH.hero(2,'Hồ sơ tài chính','& DTI','Đánh giá khả năng chi trả để xây nhà an toàn và bền vững.',{banner:false})}<div class="finance-official"><div class="finance-core"><section class="card finance-section">${BMH.sectionIcon('▥','1. Thông tin tài chính cá nhân','Cung cấp thông tin để hệ thống đánh giá khả năng chi trả phù hợp với kế hoạch xây nhà.')}<div class="fields four">${BMH.field('Số tiền hiện có','project.finance.cash',{scale:1000000,step:10,suffix:'triệu'})}${BMH.field('Thu nhập hàng tháng','project.finance.income',{scale:1000000,step:1,suffix:'triệu'})}${BMH.field('Chi phí cố định hàng tháng','project.finance.living',{scale:1000000,step:1,suffix:'triệu'})}${BMH.field('Quỹ dự phòng','project.finance.reserve',{scale:1000000,step:10,suffix:'triệu'})}</div></section><section class="card finance-section">${BMH.sectionIcon('▱','2. Thông tin khoản vay','Chọn ngân hàng để nạp kịch bản tham khảo; người dùng vẫn có thể chỉnh tay theo báo giá tín dụng thực tế.')}<div class="bank-grid official-banks">${BMH.BANKS.map(b=>`<button class="bank ${f.bank===b.id?'active':''}" data-bank="${b.id}"><img src="${b.img}" alt="${b.name}"><span>${b.name}</span><i></i></button>`).join('')}</div><div class="fields five loan-fields">${BMH.field('Số tiền vay','project.finance.loan',{scale:1000000,step:10,suffix:'triệu'})}${BMH.field('Thời hạn vay','project.finance.years',{min:1,max:35,suffix:'năm'})}${BMH.field('Lãi suất ưu đãi','project.finance.introRate',{step:.1,suffix:'%/năm'})}${BMH.field('Lãi suất sau ưu đãi','project.finance.postRate',{step:.1,suffix:'%/năm'})}${BMH.field('Thời gian ưu đãi','project.finance.promoMonths',{min:0,max:60,suffix:'tháng'})}</div><div class="bank-note"><b>${bank?.name||''}</b><span>${bank?.note||''}</span></div><div class="finance-metrics official-metrics"><div class="metric clay"><small>Khoản phải trả tháng đầu</small><strong>${BMH.money(s.first)}</strong><span>Dựa trên lãi ưu đãi ${f.introRate}%/năm</span></div><div class="metric blue"><small>Ước tính sau ưu đãi</small><strong>${BMH.money(s.post)}</strong><span>Dựa trên lãi ${f.postRate}%/năm</span></div><div class="metric ${s.dti>.35?'warn':'green'}"><small>Chỉ số an toàn dòng tiền (DTI)</small><strong>${Math.round(s.dti*100)}%</strong><span>Còn khoảng ${BMH.money(s.remainder)}/tháng</span></div></div><div class="stress official-stress"><div><h3>Kiểm tra sức chịu đựng khi lãi tăng</h3><p>Lãi suất tương lai có thể cao hơn các kịch bản minh họa. Luôn duy trì quỹ dự phòng và biên an toàn.</p></div>${stress}</div><button class="secondary" data-export="loan">${BMH.icon('download')} Tải bảng dự tính trả nợ theo tháng (Excel/CSV)</button></section></div><aside class="finance-knowledge card"><h2>Hiểu đúng để quyết định sáng suốt</h2><p>Một số khái niệm quan trọng giúp bạn lập kế hoạch tài chính an toàn hơn.</p><article><i>◇</i><div><b>Ngân sách an toàn</b><span>Nên có dự phòng 20–30% cho phát sinh và không dùng hết toàn bộ dòng tiền khả dụng.</span></div></article><article><i>%</i><div><b>Lãi thả nổi</b><span>Sau thời gian ưu đãi, lãi suất có thể điều chỉnh theo thị trường và chính sách ngân hàng.</span></div></article><article><i>▥</i><div><b>Chỉ số DTI</b><span>Tỷ lệ trả nợ trên thu nhập giúp nhận biết áp lực dòng tiền hàng tháng.</span></div></article><div class="expert-note"><span class="expert-avatar">KTS</span><div><small>Chia sẻ từ chuyên gia</small><blockquote>“Tài chính vững vàng là nền móng cho một tổ ấm bền lâu.”</blockquote></div></div></aside></div>`};

BMH.weatherCard = () => {
  const s=BMH.state.project.site,w=BMH.liveWeather,key=`${s.lat.toFixed(3)},${s.lng.toFixed(3)}`;
  if(!w||w.key!==key)return `<div id="liveWeather" class="live-weather loading"><i>◌</i><div><small>Thời tiết tại tọa độ</small><b>Đang cập nhật…</b><span>Nếu dịch vụ trực tuyến không phản hồi, dữ liệu khí hậu dài hạn bên dưới vẫn dùng bình thường.</span></div></div>`;
  if(w.error)return `<div id="liveWeather" class="live-weather fallback"><i>☁</i><div><small>Thời tiết trực tuyến</small><b>Không lấy được dữ liệu tức thời</b><span>Đang dùng hồ sơ khí hậu vùng và tọa độ dự án.</span></div></div>`;
  const days=(w.forecast||[]).map((d,i)=>`<span><small>${i===0?'Hôm nay':new Date(d.date+'T00:00:00').toLocaleDateString('vi-VN',{weekday:'short'})}</small><b>${BMH.num(d.min,0)}–${BMH.num(d.max,0)}°</b><em>☂ ${BMH.num(d.rain,0)}%</em></span>`).join('');
  return `<div id="liveWeather" class="live-weather live-weather-v38"><i>${w.precip>0?'☂':w.temp>=32?'☀':'◐'}</i><div><small>Thời tiết hiện tại · ${BMH.esc(w.timeLabel||'')}</small><b>${BMH.num(w.temp,1)}°C · ${BMH.num(w.humidity,0)}% RH</b><span>Gió ${BMH.num(w.wind,0)} km/h · Mưa ${BMH.num(w.precip,1)} mm${Number.isFinite(w.maxTemp)?` · Hôm nay ${BMH.num(w.minTemp,0)}–${BMH.num(w.maxTemp,0)}°C`:''}</span></div>${days?`<div class="forecast-strip">${days}</div>`:''}</div>`;
};

BMH.screen3 = () => {
  const s=BMH.state.project.site,r=BMH.REGIONS[s.province]||BMH.REGIONS['TP. Hồ Chí Minh'],p=BMH.regionProfile(s),adapt=BMH.siteAdaptation(s),orient=BMH.orientationAnalysis(s),parcel=BMH.siteParcelStats(s),build=BMH.buildableEnvelope(s),feas=BMH.siteFeasibility(s),drawing=BMH.state.ui.location?.drawingLot,perf=BMH.performancePlan();
  const districtOptions=(r.districts||[]).map(d=>[d[0],d[0]]),nearby=(r.districts||[]).slice(0,5),calendar=BMH.climateCalendar(p);
  const riskCards=[['Nhiệt độ',p.temp,'☀',p.heat],['Độ ẩm',p.humidity,'◌',String(p.humidity).includes('8')?'Trung bình - Cao':'Trung bình'],['Lượng mưa',p.rainfall,'☂',p.flood],['Ngập',p.flood,'⌁',p.flood],['Bão / gió mạnh',p.storm,'↯',p.storm],['Ăn mòn',p.corrosion,'◇',p.corrosion]];
  const riskClass=v=>{const n=BMH.riskValue(v);return n>=3?'risk-high':n===2?'risk-mid':'risk-low'};
  const windAngle=orient.windAngles?.[0]??135;
  return `${BMH.hero(3,'Vị trí','& Site Intelligence','Định vị khu đất bằng vệ tinh, vẽ ranh thực tế và biến khí hậu thành dữ liệu đầu vào cho thiết kế.',{banner:false})}${BMH.siteDataPanel()}
  <div class="location-official location-v40">
    <section class="card location-search">${BMH.cardTitle('Định vị khu đất','Chọn vùng, tìm địa chỉ, dùng GPS hoặc chốt trực tiếp trên ảnh vệ tinh.')}
      <div class="stack">${BMH.field('Quốc gia','project.site.country',{type:'text',hint:'Việt Nam'})}${BMH.field('Tỉnh/Thành phố hiện hành','project.site.province',{options:BMH.regionOptions()})}${BMH.field('Khu vực / phường, xã','project.site.district',{options:districtOptions})}${BMH.field('Địa chỉ cụ thể','project.site.address',{type:'text',hint:'Số nhà, đường, khu dân cư…'})}</div>
      <div class="location-actions"><button class="clay" data-geocode>${BMH.icon('pin')} Tìm đúng địa chỉ</button><button class="secondary" data-device-location>◎ Dùng vị trí thiết bị</button></div>
      <div class="location-coord"><div><b>Tọa độ dự án</b><span>${s.lat.toFixed(5)}, ${s.lng.toFixed(5)}</span></div><em>${BMH.esc(s.geoSource||'Dữ liệu vùng')}</em></div>
      <div class="admin-note"><b>Địa giới & hồ sơ pháp lý</b><span>${BMH.esc(r.adminNote||'Đối chiếu tên phường/xã hiện hành khi lập hồ sơ pháp lý.')}</span></div>
    </section>
    <section class="card map-card official-map maps-studio maps-super"><div class="map-help"><div><b>Site Lab 4.8 · Satellite / Hybrid / Google Maps</b><span>Kéo ghim, vẽ ranh đất theo ảnh vệ tinh, xem bán kính 250–500m và lớp nắng–gió.</span></div><div class="map-provider-status ${BMH.GOOGLE_MAPS_KEY?'ready':'free'}"><i>${BMH.GOOGLE_MAPS_KEY?'G':'◎'}</i><span>${BMH.GOOGLE_MAPS_KEY?'Google Maps sẵn sàng':'Free Satellite + OSM'}</span></div></div>
      <div class="map-toolbar"><div class="map-engine-switch"><button data-map-engine="free" class="${s.mapEngine!=='google'?'active':''}">Free Map</button><button data-map-engine="google" class="${s.mapEngine==='google'?'active':''}">Google Maps</button></div><div class="map-style-switch">${[['roadmap','Đường phố'],['satellite','Vệ tinh'],['hybrid','Hybrid'],['terrain','Địa hình']].map(([id,label])=>`<button data-map-style="${id}" class="${s.mapStyle===id?'active':''}">${label}</button>`).join('')}</div><div class="map-tools"><button data-map-center title="Về ghim dự án">◎</button><button data-map-lot class="${s.showLotOverlay?'active':''}" title="Hiện ranh đất">▱</button><button data-map-context class="${s.showContextRings?'active':''}" title="Bán kính 250/500m">◎</button><button data-map-climate class="${s.showClimateMap?'active':''}" title="Lớp nắng gió">☀</button><button data-map-fullscreen title="Toàn màn hình">⛶</button></div></div>
      <div id="map" class="map map-loading ${drawing?'drawing-lot':''}"><div class="map-fallback"><div class="fallback-grid"></div><div class="fallback-pin">${BMH.icon('pin')}</div><b>${BMH.esc(s.district||s.province)}</b><span>${s.lat.toFixed(4)}, ${s.lng.toFixed(4)}</span><small>Nếu dịch vụ bản đồ bị chặn, vị trí dự án và dữ liệu khí hậu vẫn không bị mất.</small></div><div class="map-climate-overlay ${s.showClimateMap?'show':''}"><div class="climate-compass"><b>N</b><span class="east">E</span><span class="south">S</span><span class="west">W</span><i class="front-bearing" style="transform:rotate(${orient.angle}deg)">↑<em>Mặt tiền</em></i><i class="wind-bearing" style="transform:rotate(${windAngle}deg)">⇢<em>Gió</em></i></div><div class="sun-track"><span>☀ sáng</span><i></i><span>☀ chiều</span></div></div><div class="map-hud"><span id="mapHudCoords">${s.lat.toFixed(5)}, ${s.lng.toFixed(5)}</span><span id="mapHudZoom">Zoom ${s.mapZoom}</span><span>${parcel.mode==='custom'?`${Math.round(parcel.area)}m² · ranh ${parcel.points.length} điểm`:`${s.width}×${s.depth}m`} · mặt tiền ${BMH.esc(s.frontDirection)}</span></div></div>
      <div class="site-lab-actions"><button data-map-draw-lot class="${drawing?'active':''}">✎ ${drawing?'Vẽ lại từ đầu':'Vẽ ranh đất'}</button><button data-map-finish-lot ${!drawing||((s.lotPoints?.length||0)<3)?'disabled':''}>✓ Hoàn tất ranh</button><button data-map-clear-lot ${s.lotMode!=='custom'?'disabled':''}>↺ Lô chữ nhật</button><span id="lotDrawStatus">${drawing?`Đang vẽ · ${s.lotPoints?.length||0} điểm · bấm các góc theo thứ tự`:parcel.mode==='custom'?`Ranh tùy chỉnh · ${parcel.points.length} điểm · ≈ ${Math.round(parcel.area)} m²`:'Lô chữ nhật theo mặt tiền × chiều sâu'}</span></div>
      <div class="map-underbar"><button data-map-retry>↻ Thử lại bản đồ</button><button data-open-google>${BMH.icon('pin')} Mở tọa độ trên Google Maps</button><button data-copy="${s.lat.toFixed(6)}, ${s.lng.toFixed(6)}">${BMH.icon('copy')} Sao chép tọa độ</button><span>${s.mapEngine==='google'?(BMH.GOOGLE_MAPS_KEY?'Google Maps Platform':'Google chưa cấu hình key · tự fallback sang Free Map'):'Ảnh vệ tinh miễn phí + OSM · có lớp dự phòng tự động'}</span></div>${BMH.weatherCard()}</section>
    <section class="card region-info official-region climate-summary">${BMH.cardTitle('Hồ sơ khí hậu khu vực')}<h3>${BMH.icon('pin')} ${BMH.esc(s.district||r.defaultDistrict)} · ${BMH.esc(s.province)}</h3><dl><div><dt>☀ Kiểu khí hậu</dt><dd>${p.climate}</dd></div><div><dt>🌡 Nhiệt độ</dt><dd>${p.temp}</dd></div><div><dt>◌ Độ ẩm</dt><dd>${p.humidity}</dd></div><div><dt>☂ Mùa mưa</dt><dd>${p.wet}</dd></div><div><dt>◒ Mùa khô</dt><dd>${p.dry}</dd></div><div><dt>↝ Gió chính</dt><dd>${p.wind}</dd></div><div><dt>₫ Nhân công</dt><dd>${p.labor}</dd></div><div class="cost-row"><dt>▥ Đường tiếp cận</dt><dd>+${Math.round(adapt.roadPct*100)}%</dd></div><div class="cost-row climate-cost"><dt>◈ Thích ứng khí hậu</dt><dd>+${Math.round(adapt.climatePct*100)}%</dd></div></dl><div class="region-source">Chi phí khí hậu là khoản dự phòng sơ bộ cho chống thấm, thoát nước, chống nóng/gió và bảo vệ vật liệu; không thay thế khảo sát kỹ thuật.</div></section>
  </div>
  <section class="card site-feasibility"><div class="between">${BMH.cardTitle('Khả năng khai thác khu đất','Tự động nối ranh đất → khoảng lùi mục tiêu → diện tích xây dựng → nhu cầu gia đình.')}<div class="feas-score ${feas.score>=80?'good':feas.score>=65?'mid':'low'}"><b>${feas.score}</b><span>/100<br>Site Fit</span></div></div><div class="site-kpis"><article><small>Diện tích lô</small><b>${BMH.num(parcel.area,0)} m²</b><span>${parcel.mode==='custom'?'Từ polygon vệ tinh':'Mặt tiền × chiều sâu'}</span></article><article><small>Khung xây tối đa theo input</small><b>${BMH.num(build.envelopeArea,0)} m²</b><span>Sau khoảng lùi sơ bộ</span></article><article><small>Mặt sàn mục tiêu</small><b>${BMH.num(build.targetPlate,0)} m²/tầng</b><span>Mật độ mục tiêu ${Math.round(build.coverage*100)}%</span></article><article><small>Tổng sàn mục tiêu</small><b>${BMH.num(build.gfa,0)} m²</b><span>${s.floors} tầng dự kiến</span></article><article><small>Nhu cầu gia đình</small><b>≈ ${BMH.num(feas.requiredGFA,0)} m²</b><span>${feas.people} người · ${feas.bedrooms} PN · ${feas.bathrooms} WC</span></article></div><div class="site-control-grid">${BMH.field('Mật độ khối xây mục tiêu','project.site.targetCoverage',{min:45,max:90,step:1,scale:.01,suffix:'%'})}${BMH.field('Khoảng lùi trước','project.site.setbackFront',{min:0,max:10,step:.1,suffix:'m'})}${BMH.field('Khoảng lùi sau','project.site.setbackRear',{min:0,max:10,step:.1,suffix:'m'})}${BMH.field('Khoảng lùi bên','project.site.setbackSide',{min:0,max:5,step:.1,suffix:'m'})}</div><div class="feas-notes">${feas.notes.map(x=>`<span>◆ ${BMH.esc(x)}</span>`).join('')}<small>Khoảng lùi/mật độ ở đây là mục tiêu thiết kế để thử phương án, không phải chỉ tiêu quy hoạch hay giấy phép xây dựng.</small></div></section>
  <section class="climate-intelligence card"><div class="between">${BMH.cardTitle('Bảng điều kiện khí hậu & rủi ro','Dùng vị trí để tác động trực tiếp đến thiết kế, vật liệu, hao mòn và dự toán.')}<span class="climate-zone-pill">${BMH.esc(p.climate)}</span></div><div class="climate-risk-grid">${riskCards.map(([name,val,ico,risk])=>`<article class="${riskClass(risk)}"><i>${ico}</i><div><small>${name}</small><b>${val}</b><span>${BMH.riskValue(risk)>=3?'Cần xử lý trong thiết kế':BMH.riskValue(risk)===2?'Cần kiểm tra theo vị trí':'Mức rủi ro tương đối thấp'}</span></div></article>`).join('')}</div></section>
  <section class="card climate-orientation"><div class="orientation-copy">${BMH.cardTitle('Hướng mặt tiền & vi khí hậu','Chọn hướng để Bước 5 đánh dấu nắng Tây, gió chủ đạo và tự sinh phương án thích ứng.')}<div class="direction-picker">${BMH.DIRECTIONS.map(([name,angle])=>`<button class="${s.frontDirection===name?'active':''}" data-front-direction="${name}"><i style="transform:rotate(${angle}deg)">↑</i><span>${name}</span></button>`).join('')}</div></div><div class="orientation-score"><div class="orientation-ring" style="--score:${orient.score}"><b>${orient.score}</b><span>/100</span></div><div><small>Hướng mặt tiền hiện tại</small><strong>${BMH.esc(orient.front)}</strong><span>Nắng: ${orient.heatLevel} · Đón gió: ${orient.windScore}/100</span></div></div><div class="orientation-notes">${orient.notes.map(x=>`<span>✓ ${BMH.esc(x)}</span>`).join('')}</div></section>
  <section class="card performance-potential"><div class="between">${BMH.cardTitle('Tiềm năng năng lượng & nước','Ước tính quy hoạch sơ bộ từ mái, hướng nhà, lượng mưa và khí hậu vùng; không thay thế thiết kế MEP/điện mặt trời chi tiết.')}<span class="performance-pill">PERFORMANCE 4.1</span></div><div class="performance-potential-grid"><article><i>☀</i><small>Mái khả dụng</small><b>${BMH.num(perf.roofArea,0)} m²</b><span>≈ ${BMH.num(perf.solarCapacity,1)} kWp tiềm năng</span></article><article><i>⚡</i><small>Sản lượng mặt trời</small><b>${BMH.num(perf.solarYield,0)} kWh/năm</b><span>Hệ số vùng ${BMH.num(perf.solarFactor,0)} kWh/kWp</span></article><article><i>☂</i><small>Nước mưa thu được</small><b>${BMH.num(perf.rainCollected,0)} m³/năm</b><span>Mái × lượng mưa × hệ số thu hồi</span></article><article><i>◒</i><small>Điện mua từ lưới</small><b>${BMH.num(perf.gridDemand,0)} kWh/năm</b><span>Đã tính giải pháp đang bật ở Bước 6</span></article></div></section>
  <section class="climate-lower-grid"><div class="card construction-window">${BMH.cardTitle('Lịch thi công theo mùa','Gợi ý sơ bộ theo mùa mưa/bão – cần cập nhật dự báo khi triển khai thực tế.')}<div class="month-grid">${calendar.map(x=>`<span class="${x.status}"><b>T${x.month}</b><em>${x.status==='good'?'Thuận lợi':x.status==='watch'?'Theo dõi':x.status==='risk'?'Rủi ro cao':'Bình thường'}</em></span>`).join('')}</div><div class="month-legend"><span class="good">Thuận lợi</span><span class="watch">Theo dõi</span><span class="risk">Rủi ro cao</span></div></div><div class="card climate-design-advice">${BMH.cardTitle('Gợi ý kiến trúc theo khí hậu','Các gợi ý này được tái sử dụng ở Bước 5, 6 và 7.')}<div class="climate-advice-list">${(p.designTips||[]).map((x,i)=>`<article><i>${['▰','⌁','☂','↝'][i%4]}</i><span>${BMH.esc(x)}</span></article>`).join('')}</div><div class="climate-facts"><span><small>Nắng / bức xạ</small><b>${BMH.esc(p.sun)}</b></span><span><small>Lượng mưa năm</small><b>${BMH.esc(p.rainfall)}</b></span></div></div></section>
  <section class="area-suggestions"><div class="between"><h2>Khu vực lân cận / điểm tham chiếu</h2><small>Chọn để chuyển nhanh tọa độ</small></div><div>${nearby.map((x,i)=>`<article data-nearby="${BMH.esc(x[0])}" data-lat="${x[1]}" data-lng="${x[2]}"><div class="area-photo area-${i+1}"></div><b>${BMH.esc(x[0])}</b><span>${i===0?'Điểm trung tâm tham chiếu':BMH.regionDistrictMeta(r,x[0]).flood?`Ngập: ${BMH.regionDistrictMeta(r,x[0]).flood}`:'Điểm khí hậu tham chiếu'}</span></article>`).join('')}</div></section>`;
};

BMH.screen4 = () => {
  const h=BMH.state.project.household,s=BMH.state.project.site,advice=BMH.householdAdvice(),needs=BMH.householdNeeds(),familyCount=needs.people,feng=BMH.fengProfile(),directionMatrix=BMH.directionDecisionMatrix(),bestDirection=directionMatrix[0];
  const shapes=['Hình chữ nhật','Hình vuông','Hình thang','Không đều'];
  const access=[['Đường lớn >5m',6],['Hẻm 3–5m',4],['Hẻm 2.5–3m',2.75],['Hẻm nhỏ <2.5m',2.2]];
  return `${BMH.hero(4,'Đất, địa chất','& phong thủy gia đình','Đánh giá điều kiện đất, địa chất, khả năng tiếp cận và nhu cầu của gia đình.',{quote:'Nền đất vững vàng – Khởi đầu tổ ấm bền lâu'})}
  <div class="step4-summary"><article><small>Diện tích lô đất</small><b>${BMH.num(s.width*s.depth)} m²</b><span>${BMH.num(s.width)} × ${BMH.num(s.depth)}m</span></article><article><small>Quy mô gia đình</small><b>${familyCount} người</b><span>Dự kiến ${needs.bedrooms} phòng ngủ</span></article><article><small>Nhu cầu WC</small><b>${needs.bathrooms}+</b><span>${needs.accessibleWC?'Có WC thuận tiện cho người lớn tuổi':'Phân bổ theo tầng'}</span></article><article><small>Khu học tập</small><b>${needs.studyZones}</b><span>${h.children.length?'Ưu tiên ánh sáng tự nhiên':'Chưa phát sinh'}</span></article></div>
  <div class="site-official"><section class="card lot-card">${BMH.sectionIcon('▤','Thông số lô đất','Nhập thông tin lô đất để đánh giá sơ bộ điều kiện xây dựng.')}<div class="fields">${BMH.field('Mặt tiền','project.site.width',{step:.1,suffix:'m'})}${BMH.field('Chiều sâu','project.site.depth',{step:.1,suffix:'m'})}${BMH.field('Số tầng dự kiến','project.site.floors',{min:1,max:5,suffix:'tầng'})}${BMH.field('Chiều rộng đường tiếp cận','project.site.road',{step:.5,suffix:'m'})}</div><h3 class="sub-label">Hình dạng lô đất</h3><div class="shape-grid">${shapes.map((n,i)=>`<button class="${s.shape===n?'active':''}" data-site-shape="${n}"><i>${['□','▢','▱','◩'][i]}</i>${n}</button>`).join('')}</div><div class="info-strip">ⓘ Hình dạng lô đất ảnh hưởng phương án thiết kế, nắng, gió và chi phí xây dựng.</div></section>
  <section class="card geology-card">${BMH.sectionIcon('▦','Địa chất & tiếp cận công trình','Đánh giá sơ bộ để lựa chọn phương án thi công phù hợp.')}<h3 class="sub-label">Loại địa chất khu vực</h3><div class="soil-grid">${[['Đất đồi cứng','◢'],['Đất thịt đồng bằng','◒'],['Đất trũng ao hồ / ven sông','≋'],['Chưa biết','?']].map(([n,ico])=>`<button class="soil ${s.soil===n?'active':''}" data-soil="${n}"><i>${ico}</i><span>${n}</span></button>`).join('')}</div><h3 class="sub-label">Khả năng tiếp cận</h3><div class="access-grid">${access.map(([n,v])=>`<button data-road-value="${v}" class="${Math.abs(s.road-v)<.4?'active':''}"><i>▥</i><span>${n}</span></button>`).join('')}</div><div class="warning-strip">⚠ Đường tiếp cận ${s.road<3?'hẹp — nên dự phòng chi phí vận chuyển/thi công cao hơn':s.road<5?'trung bình — cần kiểm tra xe vật tư và bơm bê tông':'thuận lợi hơn cho vận chuyển và tổ chức thi công'}.</div><div class="foundation-tip"><i>⚙</i><div><small>Đề xuất sơ bộ</small><b>${String(s.soil).includes('trũng')?'Cần khảo sát nền & xử lý lún':String(s.soil).includes('cứng')?'Có thể tối ưu giải pháp móng sau khảo sát':'Móng băng / móng cọc sau khảo sát'}</b><span>Chỉ chốt sau khảo sát địa chất thực tế.</span></div></div></section>
  <section class="card feng-card">${BMH.sectionIcon('◇','Phong thủy gia đình','Bát Trạch tham khảo kết hợp nhu cầu công năng thực tế.')}<div class="family-summary"><article><i>♙</i><b>Gia chủ</b><strong>${h.ownerBirth}</strong><span>${h.ownerGender}</span></article><article class="${h.partnerEnabled?'active-member':'muted-member'}"><i>♙</i><b>Người đồng hành</b><strong>${h.partnerBirth}</strong><span>${h.partnerEnabled?h.partnerGender:'Đang tắt kết hợp'}</span></article><article><i>♙</i><b>Con cái</b><strong>${h.children.length}</strong><span>người</span></article><article><i>♙</i><b>Ba mẹ/người thân</b><strong>${h.relatives.length}</strong><span>người</span></article></div>${BMH.compass()}</section></div>
  <section class="card direction-decision"><div class="between">${BMH.cardTitle('Ma trận hướng nhà · Khí hậu × phong thủy','So sánh 8 hướng bằng dữ liệu khí hậu của vị trí và Bát Trạch gia đình; đây là lớp tham khảo, không thay thế quy hoạch hay thiết kế kiến trúc.')}<div class="direction-best"><small>Gợi ý cân bằng hiện tại</small><b>${BMH.esc(bestDirection.dir)}</b><span>${bestDirection.total}/100</span></div></div><div class="direction-matrix">${directionMatrix.map(x=>`<button data-front-direction="${x.dir}" class="${s.frontDirection===x.dir?'active':''}"><i style="transform:rotate(${x.angle}deg)">↑</i><strong>${x.dir}</strong><em>${x.total}/100</em><small>Khí hậu ${x.climate} · PT ${x.feng}</small><span>${x.tag}</span></button>`).join('')}</div><div class="direction-explain"><b>${BMH.esc(feng.title)}</b><span>${BMH.esc(feng.note)}</span><small>Chọn một hướng ở đây sẽ cập nhật mặt tiền trong Bước 3, Bước 5 và mô phỏng khí hậu ở Bước 7.</small></div></section>
  <section class="card household-manager"><div class="between">${BMH.cardTitle(`Thành viên sống cùng · ${familyCount} người`,'Dữ liệu này dùng để tính nhu cầu phòng, khả năng tiếp cận và gợi ý bố trí ở Bước 5.')}<div class="row"><label class="partner-toggle"><input data-path="project.household.partnerEnabled" type="checkbox" ${h.partnerEnabled?'checked':''}><span>Kết hợp người đồng hành</span></label><button class="secondary" data-household-add="child">${BMH.icon('plus')} Thêm con</button><button class="secondary" data-household-add="relative">${BMH.icon('plus')} Thêm ba/mẹ/người thân</button></div></div><div class="core-family-edit"><label><span>Gia chủ · năm sinh</span><input data-path="project.household.ownerBirth" type="number" min="1900" max="2100" value="${h.ownerBirth}"></label><label><span>Giới tính</span><select data-path="project.household.ownerGender"><option ${h.ownerGender==='Nam'?'selected':''}>Nam</option><option ${h.ownerGender==='Nữ'?'selected':''}>Nữ</option></select></label><label><span>Người đồng hành · năm sinh</span><input data-path="project.household.partnerBirth" type="number" min="1900" max="2100" value="${h.partnerBirth}" ${h.partnerEnabled?'':'disabled'}></label><label><span>Giới tính</span><select data-path="project.household.partnerGender" ${h.partnerEnabled?'':'disabled'}><option ${h.partnerGender==='Nữ'?'selected':''}>Nữ</option><option ${h.partnerGender==='Nam'?'selected':''}>Nam</option></select></label></div><div class="household-columns"><div class="member-group"><h3>Con cái</h3>${h.children.map(c=>`<div class="person-row"><input data-person="child" data-id="${c.id}" data-key="name" value="${BMH.esc(c.name)}"><input type="number" data-person="child" data-id="${c.id}" data-key="birth" value="${c.birth}"><select data-person="child" data-id="${c.id}" data-key="room"><option ${c.room==='Riêng'?'selected':''}>Riêng</option><option ${c.room==='Ngủ chung'?'selected':''}>Ngủ chung</option></select><button data-person-remove="child" data-id="${c.id}">${BMH.icon('trash')}</button></div>`).join('')||'<p class="empty-member">Chưa thêm con.</p>'}</div><div class="member-group"><h3>Ba mẹ / người thân</h3>${h.relatives.map(r=>`<div class="person-row"><input data-person="relative" data-id="${r.id}" data-key="name" value="${BMH.esc(r.name)}"><input type="number" data-person="relative" data-id="${r.id}" data-key="birth" value="${r.birth}"><select data-person="relative" data-id="${r.id}" data-key="mobility"><option ${r.mobility==='Bình thường'?'selected':''}>Bình thường</option><option ${r.mobility==='Hạn chế nhẹ'?'selected':''}>Hạn chế nhẹ</option><option ${r.mobility==='Hạn chế nhiều'?'selected':''}>Hạn chế nhiều</option></select><button data-person-remove="relative" data-id="${r.id}">${BMH.icon('trash')}</button></div>`).join('')||'<p class="empty-member">Chưa thêm người thân.</p>'}</div></div><div class="architecture-advice"><b>Gợi ý kiến trúc từ cấu trúc gia đình</b><div>${advice.map(x=>`<span>✓ ${BMH.esc(x)}</span>`).join('')}<span>✓ Nhu cầu sơ bộ: ${needs.bedrooms} phòng ngủ · ${needs.bathrooms}+ WC${needs.groundFloorBedroom?' · ưu tiên 1 phòng ngủ tầng trệt':''}.</span></div></div></section>`;
};


BMH.plannerInspector = () => {
  const r=BMH.selectedRoom();
  if(!r)return `<div class="inspector-empty"><i>⌖</i><b>Chọn một không gian</b><span>Nhấp vào phòng trên mặt bằng để chỉnh kích thước, loại phòng và cấu kiện mở.</span></div>`;
  const openings=BMH.state.project.plan.openings.filter(o=>o.roomId===r.id), env=BMH.roomEnvironment(r), locked=BMH.isRoomLocked(r.id), suggestions=(locked||BMH.drag)?[]:BMH.roomSuggestionSpots(r,3);
  const envClass=v=>v>=78?'good':v>=60?'mid':'low';
  return `<div class="inspector-form">
    <div class="inspector-title"><div><b>${BMH.esc(r.name)}</b><span>${BMH.num(r.w*r.h)}m² · Tầng ${r.floor+1}</span></div><button data-room-delete title="Xóa phòng">${BMH.icon('trash')}</button></div>
    <label>Tên phòng<input data-room-field="name" value="${BMH.esc(r.name)}"></label>
    <label>Loại không gian<select data-room-field="type">${[['living','Phòng khách'],['kitchen','Bếp + ăn'],['bed','Phòng ngủ'],['bath','WC'],['stairs','Cầu thang'],['garage','Gara'],['corridor','Hành lang'],['balcony','Ban công']].map(([k,n])=>`<option value="${k}" ${r.type===k?'selected':''}>${n}</option>`).join('')}</select></label>
    <div class="property-grid">${['x','y','w','h'].map(k=>`<label><span>${({x:'X',y:'Y',w:'Rộng',h:'Sâu'})[k]} (m)</span><input type="number" step=".1" min="${(k==='w'||k==='h')?0.5:0}" data-room-field="${k}" value="${r[k]}"></label>`).join('')}</div>
    <div class="room-spec-row"><span><b>${BMH.num(r.w*r.h)}</b> m²</span><span><b>${BMH.num(2*(r.w+r.h))}</b> m chu vi</span><span><b>${openings.length}</b> ô mở</span></div><div class="room-lock-row"><button data-room-lock="${r.id}" class="${locked?'active':''}">${locked?'🔒 Đang khóa phòng':'🔓 Khóa vị trí phòng'}</button><span>${locked?'Phòng này được giữ nguyên khi tối ưu tự động.':'Khóa lại nếu đã chốt vị trí và không muốn AI/optimizer di chuyển.'}</span></div>${!locked?`<div class="room-suggestion-box"><b>✦ Gợi ý vị trí tốt hơn</b>${suggestions.length?suggestions.map((x,i)=>`<button data-room-suggest="${r.id}" data-x="${x.x}" data-y="${x.y}"><i>${i+1}</i><span>${x.status} · ${x.score}/100<small>Vùng ${BMH.esc(x.sector)} · X ${BMH.num(x.x,1)}m · Y ${BMH.num(x.y,1)}m</small></span><em>Đặt thử →</em></button>`).join(''):'<small>Không tìm thấy vị trí trống tốt hơn rõ rệt trong mặt bằng hiện tại.</small>'}</div>`:''}
    <div class="environment-card"><div class="environment-head"><b>Ánh sáng & thông gió</b><span>${env.crossVent?'✓ Có khả năng thông gió chéo':'Cần tối ưu thêm ô mở'}</span></div><div class="environment-meters"><label class="${envClass(env.daylight)}"><span>☀ Ánh sáng</span><i><b style="width:${env.daylight}%"></b></i><strong>${env.daylight}/100</strong></label><label class="${envClass(env.ventilation)}"><span>≋ Thông gió</span><i><b style="width:${env.ventilation}%"></b></i><strong>${env.ventilation}/100</strong></label><label class="${env.heatExposure>=70?'low':env.heatExposure>=45?'mid':'good'}"><span>♨ Nắng nóng</span><i><b style="width:${env.heatExposure}%"></b></i><strong>${env.heatExposure}/100</strong></label><label class="${envClass(env.windCapture)}"><span>↝ Đón gió</span><i><b style="width:${env.windCapture}%"></b></i><strong>${env.windCapture}/100</strong></label></div><small>${env.windows} cửa sổ ngoài · ${BMH.num(env.totalWidth,1)}m ô thoáng · mặt tiền ${BMH.esc(BMH.state.project.site.frontDirection)}</small></div>
    <div class="opening-actions"><button class="${BMH.state.ui.planner.tool==='door'?'active':''}" data-add-opening="door">↪ Đặt cửa đi</button><button class="${BMH.state.ui.planner.tool==='window'?'active':''}" data-add-opening="window">▥ Đặt cửa sổ</button></div>
    <div class="opening-list"><b>Cấu kiện mở</b>${openings.length?openings.map(o=>`<div class="opening-row"><span class="opening-code">${BMH.openingCode(o)}</span><select data-opening-field="side" data-opening-id="${o.id}">${[['north','Bắc'],['south','Nam'],['east','Đông'],['west','Tây']].map(([k,n])=>`<option value="${k}" ${o.side===k?'selected':''}>${n}</option>`).join('')}</select><label><input type="number" step=".1" min=".5" max="3" data-opening-field="width" data-opening-id="${o.id}" value="${o.width}">m</label><label class="opening-offset" title="Vị trí dọc theo tường"><input type="range" min="0" max="1" step=".05" data-opening-field="offset" data-opening-id="${o.id}" value="${o.offset??.5}"></label><button data-opening-delete="${o.id}" title="Xóa">×</button></div>`).join(''):'<span class="empty-opening">Chưa có cửa/cửa sổ.</span>'}</div>
  </div>`;
};


