    <div class="design-mode-tabs"><button class="${BMH.state.ui.designTab==='sample'?'active':''}" data-design-tab="sample">▧ Ảnh nhà mẫu</button><button class="${BMH.state.ui.designTab==='upload'?'active':''}" data-design-tab="upload">▤ Tải bản vẽ</button><button class="${plannerMode?'active':''}" data-design-tab="planner">✎ Tự thiết kế</button></div>
