BMH.isoModel = () => {
  const p=BMH.state.project,ui=BMH.state.ui,focus=ui.sceneFocus,theme=ui.sceneTheme,zStep=ui.sceneExploded?3.8:3;
  let rooms=p.plan.rooms.filter(r=>focus==='all'||focus===`floor:${r.floor}`||focus===`room:${r.id}`);
  if(!rooms.length) rooms=p.plan.rooms.slice();
  const paint=p.materials.choices.paint==='jotun'?'#e7d6c1':'#f0ebe2', floor=p.materials.choices.floor==='vietceramics'?'#cbb59c':p.materials.choices.floor==='dongtam'?'#d9c8ad':'#ddd7cc', door=p.materials.choices.door==='premium-door'?'#303433':'#544c45';
  const minX=Math.min(...rooms.map(r=>r.x)),minY=Math.min(...rooms.map(r=>r.y)),minF=Math.min(...rooms.map(r=>r.floor));
  const rel=rooms.map(r=>({...r,x:r.x-minX,y:r.y-minY,floor:r.floor-minF})), idMap=new Map(rel.map((r,i)=>[rooms[i].id,r]));
  const maxX=Math.max(...rel.map(r=>r.x+r.w)),maxY=Math.max(...rel.map(r=>r.y+r.h)),maxF=Math.max(...rel.map(r=>r.floor));
  let S=46; const rawW=(maxX+maxY)*S,rawH=(maxX+maxY)*S*.46+(maxF*zStep+2.8)*S*.74;S*=Math.min(1.55,710/Math.max(260,rawW),350/Math.max(180,rawH));S=Math.max(25,S);
  const proj=(x,y,z=0)=>[(x-y)*S,(x+y)*S*.46-z*S*.74];
  const all=[];rel.forEach(r=>[[r.x,r.y],[r.x+r.w,r.y],[r.x+r.w,r.y+r.h],[r.x,r.y+r.h]].forEach(([x,y])=>all.push(proj(x,y,r.floor*zStep+2.75))));
  const xs=all.map(q=>q[0]),ys=all.map(q=>q[1]),dx=450-(Math.min(...xs)+Math.max(...xs))/2,dy=276-(Math.min(...ys)+Math.max(...ys))/2;
  const P=(x,y,z=0)=>{const q=proj(x,y,z);return [q[0]+dx,q[1]+dy]};
  const pts=a=>a.map(q=>q.join(',')).join(' '),poly=(a,fill,stroke='#5e6c64',extra='')=>`<polygon points="${pts(a)}" fill="${fill}" stroke="${stroke}" ${extra}/>`;
  const floorPoly=r=>poly([[r.x,r.y],[r.x+r.w,r.y],[r.x+r.w,r.y+r.h],[r.x,r.y+r.h]].map(([x,y])=>P(x,y,r.floor*3+.03)),floor,'#647168','opacity=".98"');
  const rearWalls=r=>{const z=r.floor*zStep,h=2.7,n=[P(r.x,r.y,z),P(r.x+r.w,r.y,z),P(r.x+r.w,r.y,z+h),P(r.x,r.y,z+h)],e=[P(r.x+r.w,r.y,z),P(r.x+r.w,r.y+r.h,z),P(r.x+r.w,r.y+r.h,z+h),P(r.x+r.w,r.y,z+h)];return poly(n,paint,'#617067','opacity=".94"')+poly(e,r.type==='bath'?'#d9e5e5':'#ddd5ca','#617067','opacity=".94"')};
  const furn=r=>{const z=r.floor*zStep+.10,items=[],rect=(x,y,w,h,c)=>poly([[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>P(a,b,z)),c,'#7a827e','opacity=".96"');if(r.type==='bed'){items.push(rect(r.x+r.w*.16,r.y+r.h*.18,r.w*.66,r.h*.52,'#f4efe7'));items.push(rect(r.x+r.w*.22,r.y+r.h*.20,r.w*.22,r.h*.12,'#fff'));}else if(r.type==='living'){items.push(rect(r.x+r.w*.10,r.y+r.h*.18,r.w*.58,r.h*.20,'#cfd7cf'));items.push(rect(r.x+r.w*.36,r.y+r.h*.55,r.w*.30,r.h*.18,'#c7b69b'));}else if(r.type==='kitchen'){items.push(rect(r.x+r.w*.06,r.y+r.h*.10,r.w*.88,r.h*.13,'#bca98d'));items.push(rect(r.x+r.w*.32,r.y+r.h*.52,r.w*.36,r.h*.20,'#e8e1d6'));}else if(r.type==='bath'){items.push(rect(r.x+r.w*.10,r.y+r.h*.14,r.w*.30,r.h*.26,'#dce9ea'));items.push(rect(r.x+r.w*.57,r.y+r.h*.58,r.w*.28,r.h*.24,'#edf3f3'));}else if(r.type==='stairs'){for(let i=0;i<8;i++)items.push(rect(r.x+r.w*.16,r.y+r.h*(.10+i*.09),r.w*.68,r.h*.045,'#d8d3c9'));}return items.join('')};
  const openingMarkup=p.plan.openings.map(o=>{const rr=idMap.get(o.roomId);if(!rr)return'';const z=rr.floor*zStep,w=Math.min(o.width||.9,o.side==='north'||o.side==='south'?rr.w:rr.h),off=BMH.clamp(o.offset??.3,0,1);if(o.side==='north'){const x=rr.x+(rr.w-w)*off,a=P(x,rr.y,z+(o.kind==='door'?0:.8)),b=P(x+w,rr.y,z+(o.kind==='door'?0:.8)),c=P(x+w,rr.y,z+(o.kind==='door'?2.1:1.9)),d=P(x,rr.y,z+(o.kind==='door'?2.1:1.9));return poly([a,b,c,d],o.kind==='door'?door:'#9fc7d6','#405850',`opacity="${o.kind==='door'?'.92':'.72'}"`)}if(o.side==='east'){const y=rr.y+(rr.h-w)*off,a=P(rr.x+rr.w,y,z+(o.kind==='door'?0:.8)),b=P(rr.x+rr.w,y+w,z+(o.kind==='door'?0:.8)),c=P(rr.x+rr.w,y+w,z+(o.kind==='door'?2.1:1.9)),d=P(rr.x+rr.w,y,z+(o.kind==='door'?2.1:1.9));return poly([a,b,c,d],o.kind==='door'?door:'#9fc7d6','#405850',`opacity="${o.kind==='door'?'.92':'.72'}"`)}return''}).join('');
  const sorted=[...rel].sort((a,b)=>(a.floor-b.floor)||((a.x+a.y)-(b.x+b.y)));
  const slabs=Array.from({length:maxF+1},(_,f)=>{const rs=rel.filter(r=>r.floor===f);if(!rs.length)return'';const mx=Math.max(...rs.map(r=>r.x+r.w)),my=Math.max(...rs.map(r=>r.y+r.h)),z=f*zStep;return poly([[0,0],[mx,0],[mx,my],[0,my]].map(([x,y])=>P(x,y,z-.10)),theme==='night'?'#2f3735':'#e6e3da','#6f7973','opacity=".68"')}).join('');
  const markup=sorted.map(r=>{const center=P(r.x+r.w/2,r.y+r.h/2,r.floor*zStep+.12);return `<g class="iso-room iso-${r.type}">${floorPoly(r)}${rearWalls(r)}${furn(r)}<text x="${center[0]}" y="${center[1]}" text-anchor="middle">${BMH.esc(r.name)}</text></g>`}).join('');
  const visibleFloors=[...new Set(rooms.map(r=>r.floor))];
  const columnMarkup=visibleFloors.flatMap(f=>BMH.suggestedColumns(f).map(c=>{const x=c.x-minX,y=c.y-minY,z=(f-minF)*zStep,a=P(x,y,z),b=P(x,y,z+2.7);return `<line class="iso-column" x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/>`;})).join('');
  const roofMarkup=focus.startsWith('room:')?'':(()=>{const z=maxF*zStep+2.82,ov=.16;return `<g class="iso-roof">${poly([[-ov,-ov],[maxX+ov,-ov],[maxX+ov,maxY+ov],[-ov,maxY+ov]].map(([x,y])=>P(x,y,z)),theme==='night'?'#404846':'#f0ece3','#667168','opacity=".92"')}<line x1="${P(maxX*.18,0,z+.05)[0]}" y1="${P(maxX*.18,0,z+.05)[1]}" x2="${P(maxX*.18,maxY*.34,z+.05)[0]}" y2="${P(maxX*.18,maxY*.34,z+.05)[1]}" class="iso-pergola"/><line x1="${P(maxX*.42,0,z+.05)[0]}" y1="${P(maxX*.42,0,z+.05)[1]}" x2="${P(maxX*.42,maxY*.34,z+.05)[0]}" y2="${P(maxX*.42,maxY*.34,z+.05)[1]}" class="iso-pergola"/></g>`;})();
  const balconyMarkup=rel.filter(r=>r.type==='balcony').map(r=>{const z=r.floor*zStep+1.05,a=P(r.x,r.y+r.h,z),b=P(r.x+r.w,r.y+r.h,z),c=P(r.x,r.y+r.h,z+1.0),d=P(r.x+r.w,r.y+r.h,z+1.0);return `<g class="iso-balcony-rail"><line x1="${a[0]}" y1="${a[1]}" x2="${c[0]}" y2="${c[1]}"/><line x1="${b[0]}" y1="${b[1]}" x2="${d[0]}" y2="${d[1]}"/><line x1="${c[0]}" y1="${c[1]}" x2="${d[0]}" y2="${d[1]}"/></g>`}).join('');
  const landscapeMarkup=focus==='all'?(()=>{const lawn=poly([[-.6,maxY+.35],[maxX+.8,maxY+.35],[maxX+.8,maxY+2.1],[-.6,maxY+2.1]].map(([x,y])=>P(x,y,0)),theme==='night'?'#314039':'#cfdcc7','#7f907f','opacity=".75"');const drive=poly([[maxX*.55,maxY+.25],[maxX+.25,maxY+.25],[maxX+.25,maxY+1.75],[maxX*.55,maxY+1.75]].map(([x,y])=>P(x,y,.02)),theme==='night'?'#465052':'#d7d5cd','#929792','opacity=".94"');return `<g class="iso-site-context">${lawn}${drive}</g>`;})():'';
  const label=focus.startsWith('room:')?rooms[0]?.name:focus.startsWith('floor:')?`Tầng ${Number(focus.split(':')[1])+1}`:'Toàn bộ công trình';
  return `<svg viewBox="0 0 900 520" class="iso-svg iso-cutaway ${theme==='night'?'iso-night':''}" aria-label="Mô hình 3D phương án"><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${theme==='night'?'#172331':'#dcebdd'}"/><stop offset="1" stop-color="${theme==='night'?'#2c3540':'#f6f3ea'}"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="12" stdDeviation="10" flood-opacity=".18"/></filter></defs><rect width="900" height="520" fill="url(#sky)"/><ellipse cx="450" cy="430" rx="330" ry="62" fill="${theme==='night'?'#1e292c':'#dbe3d7'}" opacity=".8"/>${landscapeMarkup}<g filter="url(#shadow)">${slabs}${markup}${openingMarkup}<g class="iso-columns">${columnMarkup}</g>${balconyMarkup}${roofMarkup}</g><g class="iso-title"><rect x="28" y="28" width="286" height="64" rx="16"/><text x="48" y="54">3D CUTAWAY · ${BMH.esc(label||'')}</text><text class="sub" x="48" y="76">Mặt bằng Bước 5 + vật liệu Bước 6${ui.sceneExploded?' · tách tầng':''}</text></g><g class="iso-materials"><rect x="637" y="28" width="235" height="88" rx="16"/><circle cx="663" cy="53" r="9" fill="${floor}"/><text x="681" y="57">Sàn · ${BMH.esc(p.materials.choices.floor)}</text><circle cx="663" cy="80" r="9" fill="${paint}"/><text x="681" y="84">Sơn · ${BMH.esc(p.materials.choices.paint)}</text><circle cx="663" cy="104" r="9" fill="${door}"/><text x="681" y="108">Cửa · ${BMH.esc(p.materials.choices.door)}</text></g><g class="iso-orientation"><circle cx="842" cy="444" r="27"/><path d="M842 420l8 24-8-5-8 5z"/><text x="842" y="413">N</text></g><g class="iso-note"><rect x="30" y="444" width="312" height="45" rx="12"/><text x="48" y="464">Mô hình sơ bộ · mở mái để nhìn công năng</text><text class="sub" x="48" y="482">Không thay thế phối cảnh kiến trúc / BIM thi công</text></g></svg>`;
};

BMH.screen7 = () => {const ui=BMH.state.ui,review=BMH.designReview(),profile=BMH.regionProfile(BMH.state.project.site),perf=BMH.performancePlan(),wearFactor=(1+(BMH.riskValue(profile.flood)+BMH.riskValue(profile.storm)+BMH.riskValue(profile.corrosion))*0.05)*({economy:1.14,standard:1,premium:.82}[BMH.state.project.materials.tier]||1),year=BMH.state.project.wearYear,roomOptions=BMH.state.project.plan.rooms.map(r=>`<option value="room:${r.id}" ${ui.sceneFocus===`room:${r.id}`?'selected':''}>T${r.floor+1} · ${BMH.esc(r.name)}</option>`).join(''),wear={0:['Hiện tại','Bề mặt mới, chưa có dấu hiệu hao mòn.',0,'new'],3:['Năm 3',`Bạc màu nhẹ tại khu vực nắng gắt; khí hậu ${profile.climate.toLowerCase()} bắt đầu tác động ron và lớp phủ.`,Math.round(19000000*wearFactor),'y3'],5:['Năm 5',`Nứt chân chim cục bộ, bạc màu và nguy cơ thấm tăng; rủi ro ngập/bão vùng: ${profile.flood} / ${profile.storm}.`,Math.round(35000000*wearFactor),'y5'],10:['Năm 10',`Rêu mốc, bạc màu, nứt bề mặt và ăn mòn tích lũy; mức ăn mòn vùng: ${profile.corrosion}.`,Math.round(62000000*wearFactor),'y10']}[year];return `${BMH.hero(7,'Mô phỏng 3D','& đánh giá AI','Xem trước ngôi nhà, nội thất và tác động hao mòn theo thời gian trước khi quyết định.',{quote:'Nhìn thấy tương lai của ngôi nhà ngay từ hôm nay'})}<div class="visual-review"><aside class="review-score card"><h2>Đánh giá tổng thể</h2><div class="score-ring" style="--score:${review.overall}"><b>${review.overall}</b><span>/ 100</span></div><p>Phương án của bạn khá tốt!<br>Chỉ cần tối ưu một vài hạng mục.</p>${[['Ngân sách',review.budget],['Công năng',review.function],['Khí hậu',review.climate],['Năng lượng',review.energy],['Vật liệu',review.material],['Site Fit',review.siteFit],['Phong thủy',review.feng],['Độ bền',review.durability]].map(([n,v])=>`<div class="score-row"><span>${n}</span><i><b style="width:${v}%"></b></i><em>${v}/100</em></div>`).join('')}</aside><section class="scene-center"><div class="scene-toolbar official-scene-toolbar"><div class="tabs"><button class="${ui.sceneMode==='reference'?'active':''}" data-scene-mode="reference">▣ 3D ngoại thất</button><button class="${ui.sceneMode==='model'?'active':''}" data-scene-mode="model">▱ 3D phương án</button><button data-wear="5" class="${year===5?'active':''}">◷ Hao mòn 5 năm</button><button data-wear="10" class="${year===10?'active':''}">◷ Hao mòn 10 năm</button></div><div class="scene-select"><button class="scene-explode ${ui.sceneExploded?'active':''}" data-scene-explode>⇳ ${ui.sceneExploded?'Ghép tầng':'Tách tầng'}</button><select data-scene-focus><option value="all">Toàn bộ công trình</option>${Array.from({length:BMH.state.project.site.floors},(_,i)=>`<option value="floor:${i}" ${ui.sceneFocus===`floor:${i}`?'selected':''}>Tầng ${i+1}</option>`).join('')}${roomOptions}</select></div></div><div class="scene-stage official-scene-stage">${ui.sceneMode==='model'?`<div class="scene-model premium-model wear-${wear[3]}">${BMH.isoModel()}<div class="model-glass"><b>3D PHƯƠNG ÁN</b><span>Geometry từ Bước 5 · vật liệu từ Bước 6</span></div></div>`:`<div class="reference-scene wear-${wear[3]} ${ui.sceneTheme==='night'?'night':''}"><div class="wear-badge">${wear[0]}</div><img src="assets/rooms/facade-render.jpg" alt="Phối cảnh"><div class="wear-overlay"></div><div class="weathering weathering-${wear[3]}"><i></i><i></i><i></i></div><div class="callout c1"><i>☀</i><b>Mặt Tây nhận nhiều nắng</b><span>Nên bố trí lam che</span></div><div class="callout c2"><i>◉</i><b>Ban công</b><span>Cần chống thấm kỹ</span></div><div class="callout c3"><i>≋</i><b>Phòng ngủ</b><span>Nên tăng thông gió</span></div></div>`}<button class="theme-toggle floating-theme" data-scene-theme>${ui.sceneTheme==='day'?'Ngày':'Đêm'}</button></div><div class="scene-analysis-strip"><article><i>☀</i><div><small>Ánh sáng tự nhiên</small><b>${review.daylight}/100</b><span>${review.daylight>=78?'Tốt':review.daylight>=60?'Khá · còn điểm cần tối ưu':'Thiếu sáng ở một số không gian'}</span></div></article><article><i>≋</i><div><small>Thông gió tự nhiên</small><b>${review.ventilation}/100</b><span>${review.ventilation>=78?'Thông thoáng tốt':review.ventilation>=60?'Mức khá':'Cần thêm ô mở/thông gió chéo'}</span></div></article><article><i>⇅</i><div><small>Phối hợp tầng</small><b>${BMH.coordinationIssues(BMH.state.ui.planner.floor).length?'Cần xem':'Ổn'}</b><span>Cầu thang · khu ướt · trục đứng</span></div></article><article><i>↝</i><div><small>Lưu thông</small><b>${review.circulation}/100</b><span>${review.circulation>=80?'Tuyến đi rõ ràng':review.circulation>=60?'Còn điểm nghẽn cần xem':'Cần tổ chức lại cửa & hành lang'}</span></div></article><article><i>◒</i><div><small>Hướng & vi khí hậu</small><b>${review.orientation}/100</b><span>Mặt tiền ${BMH.esc(BMH.state.project.site.frontDirection)}</span></div></article><article><i>◎</i><div><small>Site Fit</small><b>${review.siteFit}/100</b><span>${Math.round(BMH.siteParcelStats(BMH.state.project.site).area)}m² · khung ${Math.round(BMH.buildableEnvelope(BMH.state.project.site).targetPlate)}m²/tầng</span></div></article></div><div class="scene-model-metrics"><article><small>Diện tích phương án</small><b>${BMH.num(BMH.planArea())} m²</b></article><article><small>Số tầng</small><b>${BMH.state.project.site.floors} tầng</b></article><article><small>Cửa / cửa sổ</small><b>${BMH.state.project.plan.openings.filter(o=>o.kind==='door').length} / ${BMH.state.project.plan.openings.filter(o=>o.kind==='window').length}</b></article><article><small>Gói vật liệu</small><b>${BMH.state.project.materials.tier==='premium'?'Cao cấp':BMH.state.project.materials.tier==='economy'?'Tiết kiệm':'Tiêu chuẩn'}</b></article><article><small>Thích ứng khí hậu</small><b>${({basic:'Cơ bản',recommended:'Khuyến nghị',robust:'Tăng cường'})[BMH.state.project.materials.climatePackage]||'Khuyến nghị'}</b></article></div><div class="wear-summary"><b>Dự báo hao mòn sau ${year||0} năm</b><div><article><span class="wear-thumb crack"></span><b>Nứt chân tường</b><small>${year>=5?'Có thể xuất hiện cục bộ':'Nguy cơ thấp'}</small></article><article><span class="wear-thumb fade"></span><b>Bạc màu sơn</b><small>${year>=3?'Màu sơn có thể giảm độ tươi':'Chưa đáng kể'}</small></article><article><span class="wear-thumb damp"></span><b>Nguy cơ thấm nước</b><small>${year>=5?'Cần kiểm tra chi tiết ban công/WC':'Thấp'}</small></article></div></div></section><aside class="review-comments"><article class="card"><h2>✦ Nhận xét từ AI</h2><p>${review.issues.length?`Hệ thống phát hiện ${review.issues.length} lưu ý trên mặt bằng. ${BMH.esc(review.issues[0]?.text||'')}`:'Mặt bằng hiện không có xung đột hình học cơ bản. Tiếp tục kiểm tra ánh sáng, thông gió và chi tiết khu ướt.'}</p></article><article class="card"><h2>Nhận xét theo khí hậu</h2><p><b>${BMH.esc(BMH.state.project.site.district)}</b>: ${BMH.esc(BMH.orientationAnalysis(BMH.state.project.site).notes[0]||profile.designTips?.[0]||'Ưu tiên bóng râm và thông gió chéo.')} ${BMH.esc(profile.designTips?.[1]||'')}</p><small>Mặt tiền: ${BMH.esc(BMH.state.project.site.frontDirection)} · Nắng: ${BMH.esc(profile.sun)} · Gió: ${BMH.esc(profile.wind)}</small></article><article class="card site-review-mini"><h2>◎ Site Intelligence</h2><p><b>${review.siteFit}/100</b> · ${BMH.esc(BMH.siteFeasibility(BMH.state.project.site).notes[0]||'Quỹ đất đang ở mức cân bằng.')}</p><small>Ranh: ${BMH.state.project.site.lotMode==='custom'?'polygon vệ tinh':'chữ nhật'} · Mật độ mục tiêu ${Math.round(BMH.state.project.site.targetCoverage*100)}%</small></article><article class="card feng-mini"><h2>◇ Nhận xét phong thủy</h2><div class="mini-score"><b>75</b><span>/100</span></div><p>Hướng tham khảo phù hợp: <b>${BMH.fengProfile()?.dirs?.[0]||'—'}</b></p></article></aside></div><section class="card performance-review"><div class="between">${BMH.cardTitle('Hiệu năng vận hành 4.8','Đọc cùng một dữ liệu từ vị trí, khí hậu, mặt bằng và hệ thống đã chọn ở Bước 6.')}<span class="performance-pill">LIVE MODEL</span></div><div class="performance-review-grid"><article><div class="score-ring mini" style="--score:${perf.energyScore}"><b>${perf.energyScore}</b></div><span><small>Hiệu quả năng lượng</small><strong>${BMH.num(perf.gridDemand,0)} kWh/năm mua lưới</strong></span></article><article><div class="score-ring mini" style="--score:${perf.comfortScore}"><b>${perf.comfortScore}</b></div><span><small>Tiện nghi thụ động</small><strong>Giảm tải ${Math.round(perf.passiveReduction*100)}%</strong></span></article><article><div class="score-ring mini" style="--score:${perf.waterScore}"><b>${perf.waterScore}</b></div><span><small>Nước & chống chịu</small><strong>${BMH.num(perf.rainReuse,0)} m³/năm tái sử dụng</strong></span></article><article class="performance-money"><i>₫</i><span><small>Chi phí điện mô phỏng</small><strong>${BMH.money(perf.annualElectricCost)}/năm</strong><em>Tiết kiệm ${BMH.money(perf.annualSavings)}/năm</em></span></article></div><div class="performance-flow"><span>Vị trí & khí hậu</span><b>→</b><span>Hướng + mặt bằng</span><b>→</b><span>Vật liệu & hệ thống</span><b>→</b><span>Điện · nước · tiện nghi</span></div></section><section class="time-machine"><span class="eyebrow">TUA NHANH VÒNG ĐỜI</span><div class="wear-timeline">${[0,3,5,10].map(y=>`<button class="${year===y?'active':''}" data-wear="${y}"><i>${y===0?'●':y}</i><span>${y===0?'Hiện tại':`Năm ${y}`}</span></button>`).join('')}</div><div class="wear-info"><b>${wear[0]}</b><span>${wear[1]}</span><strong>${BMH.money(wear[2])}<em>quỹ bảo trì minh họa</em></strong></div></section>`};

BMH.screen8 = () => {const e=BMH.estimate(),paid=BMH.isUnlocked(),perf=BMH.performancePlan();const rows=[['Móng',e.shell*.25],['Kết cấu',e.shell*.45],['Tường & xây tô',e.shell*.30],['Điện nước (MEP)',e.finish*.22],['Hoàn thiện',e.finish*.58],['Nội thất',e.finish*.20],...(e.climatePrep>0?[['Thích ứng khí hậu',e.climatePrep]]:[]),...(e.performanceUpgrade>0?[['Năng lượng & nước bền vững',e.performanceUpgrade]]:[]),['Dự phòng',e.contingency]];return `${BMH.hero(8,'Dự toán','& thanh toán','Xem miễn phí dự toán tổng quan, sau đó mở khóa bước giám sát thi công.',{quote:'Dự toán minh bạch – Kiểm soát chi phí, an tâm thi công'})}<div class="estimate-official"><section class="estimate-left card">${BMH.cardTitle('Bảng dự toán tổng quan')}${BMH.estimateDataStrip()}<div class="estimate-two"><div class="tablewrap"><table><thead><tr><th>Hạng mục</th><th>Giá trị</th><th>Tỷ trọng</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td>${BMH.money(v)}</td><td>${Math.round(v/e.total*100)}%</td></tr>`).join('')}<tr class="total"><td>Tổng cộng</td><td>${BMH.money(e.total)}</td><td>100%</td></tr></tbody></table></div><div class="cost-structure"><h3>Cơ cấu chi phí xây dựng</h3><div class="donut" style="--shell:${Math.round(e.shell/e.total*100)};--finish:${Math.round(e.finish/e.total*100)}"><b>${BMH.num(e.total/1000000,0)}</b><small>triệu VND</small></div><div class="legend"><span><i class="l1"></i>Phần thô <b>${Math.round(e.shell/e.total*100)}%</b></span><span><i class="l2"></i>Hoàn thiện <b>${Math.round(e.finish/e.total*100)}%</b></span><span><i class="l3"></i>Dự phòng <b>${Math.round(e.contingency/e.total*100)}%</b></span></div></div></div><div class="budget-compare official-budget"><article><small>Ngân sách của bạn</small><b>${BMH.money(e.budget)}</b></article><article><small>Tổng dự toán</small><b>${BMH.money(e.total)}</b></article><article class="${e.gap>=0?'good':'bad'}"><small>${e.gap>=0?'Còn dư khoảng':'Vượt ngân sách'}</small><b>${BMH.money(Math.abs(e.gap))}</b></article></div><div class="lifecycle-panel"><div><small>Chi phí vận hành điện 10 năm</small><b>${BMH.money(perf.tenYearOps)}</b><span>Không tính trượt giá điện</span></div><div><small>Tiết kiệm điện + nước 10 năm</small><b>${BMH.money(perf.tenYearSavings)}</b><span>Theo cấu hình Performance Studio</span></div><div><small>Hoàn vốn hệ thống</small><b>${perf.payback?`${BMH.num(perf.payback,1)} năm`:'—'}</b><span>${perf.solarCoverage}% nhu cầu điện được bù bởi solar tự dùng</span></div><div class="lifecycle-total"><small>Tổng góc nhìn 10 năm</small><b>${BMH.money(e.total+perf.tenYearOps)}</b><span>Chi phí xây dựng + điện vận hành mô phỏng</span></div></div><div class="recommendations"><div><h3>Nhà thầu gợi ý tại ${BMH.state.project.site.province}</h3><span>★ 4.8 · An Phát &nbsp;&nbsp; ★ 4.8 · Kiến Tạo Việt</span></div><div><h3>Nhà cung cấp vật liệu uy tín</h3><span>Dulux · INSEE · INAX · Viglacera</span></div></div></section>${BMH.paymentPanel(paid)}</div>`};

BMH.screen9 = () => {if(!BMH.isUnlocked())return BMH.lockedScreen(9);const c=BMH.state.project.checklist,items=[['pipe114','Ống thoát toilet Φ114 (độ dốc ≥ 1%)'],['acWire','Dây điện máy lạnh 4.0 mm² đi riêng'],['pressure','Test áp lực ống nước theo hồ sơ kỹ thuật'],['internet','Ống chờ internet/camera'],['elcb','Tiếp địa & chống rò ELCB/RCBO']];const stages=[['Móng','♨'],['Kết cấu','▦'],['Tường','▤'],['Mái','⌂'],['Điện nước','⌁'],['Hoàn thiện','▥'],['Nội thất & bàn giao','▱']];return `<div class="success-banner">✓ <div><b>Thanh toán thành công — Bước 9 đã mở khóa</b><span>Bạn có thể sử dụng đầy đủ tính năng giám sát thi công, checklist MEP và cập nhật tiến độ dự án.</span></div></div>${BMH.hero(9,'Giám sát thi công','& checklist MEP','Giám sát tiến độ, chất lượng và nghiệm thu các hạng mục kỹ thuật.',{banner:false})}<div class="construction-stages">${stages.map(([n,ico],i)=>`<span class="${i===1?'active':''}"><i>${ico}</i><b>${i+1}. ${n}</b></span>`).join('')}</div><div class="supervision-official"><section class="card schedule-card"><h2>Kế hoạch thi công & giải ngân</h2><div class="tablewrap"><table><thead><tr><th>STT</th><th>Hạng mục thi công</th><th>Thời gian dự kiến</th><th>Tỷ lệ</th><th>Số tiền</th></tr></thead><tbody>${[['Móng','Tháng 03/2026',10],['Kết cấu','Tháng 04–05/2026',20],['Tường','Tháng 06/2026',15],['Mái','Tháng 07/2026',10],['Điện nước','Tháng 08/2026',15],['Hoàn thiện','Tháng 09–10/2026',20],['Nội thất & bàn giao','Tháng 11/2026',10]].map((r,i)=>`<tr class="${i===1?'highlight':''}"><td>${i+1}</td><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}%</td><td>${BMH.money(BMH.estimate().total*r[2]/100)}</td></tr>`).join('')}<tr class="total"><td colspan="3">Tổng cộng</td><td>100%</td><td>${BMH.money(BMH.estimate().total)}</td></tr></tbody></table></div></section><section class="card progress-card"><h2>Tiến độ thi công hiện tại</h2><div class="site-photo"></div><div class="progress-figure"><b>35%</b><i><span style="width:35%"></span></i></div><dl><div><dt>Hạng mục hiện tại</dt><dd>Kết cấu</dd></div><div><dt>Dự kiến hoàn thành</dt><dd>Tháng 05/2026</dd></div></dl><div class="month-budget"><b>Kế hoạch chuẩn bị ngân sách theo tháng</b><div><span>T03<br><strong>150tr</strong></span><span>T04<br><strong>200tr</strong></span><span>T05<br><strong>100tr</strong></span><span>T06<br><strong>225tr</strong></span></div></div></section><section class="card checklist official-checklist"><h2>Checklist kỹ thuật MEP</h2>${items.map(([k,n])=>`<label><input type="checkbox" data-check="${k}" ${c[k]?'checked':''}><span>${n}</span></label>`).join('')}<button class="clay" data-print>${BMH.icon('download')} Tải checklist (PDF)</button><small>Đối chiếu hồ sơ kỹ thuật và nghiệm thu thực tế trước khi ký xác nhận.</small></section></div>`};

BMH.screen10 = () => {if(!BMH.isUnlocked())return BMH.lockedScreen(10);const e=BMH.estimate();return `${BMH.hero(10,'Hồ sơ bàn giao','& giải ngân','Tải trọn bộ hồ sơ, kế hoạch giải ngân và tài liệu bàn giao sau khi hoàn tất hành trình.',{quote:'Một hành trình đẹp kết thúc bằng một tổ ấm trọn vẹn'})}<div class="handover-official"><section class="handover-main"><div class="card download-center"><div class="between">${BMH.cardTitle('Trung tâm tải hồ sơ','Tải từng tài liệu hoặc tải trọn bộ để lưu lại toàn bộ hồ sơ dự án của bạn.')}<span class="ready-pill">✓ Sẵn sàng bàn giao</span></div><div class="download-grid official-downloads"><button data-print><i>PDF</i><b>Hồ sơ tổng hợp</b><span>Toàn bộ hồ sơ dự án</span><em>Tải xuống</em></button><button data-export="estimate"><i>X</i><b>Bóc tách chi phí</b><span>Dự toán & thanh toán</span><em>Tải xuống</em></button><button data-print><i>PDF</i><b>Checklist MEP</b><span>Danh mục kiểm tra</span><em>Tải xuống</em></button><button data-export="plan"><i>SVG</i><b>Hồ sơ vật liệu & mặt bằng</b><span>Thông số & bản vẽ vector</span><em>Tải xuống</em></button><button data-export="json"><i>JSON</i><b>Dữ liệu dự án</b><span>Bản sao dữ liệu</span><em>Tải xuống</em></button></div></div><div class="handover-bottom"><section class="card"><h2>Kế hoạch giải ngân & bàn giao</h2><div class="tablewrap"><table><thead><tr><th>Giai đoạn</th><th>Tỷ lệ thanh toán</th><th>Số tiền</th><th>Mốc nghiệm thu</th></tr></thead><tbody>${[['Ký hợp đồng',10,'Ký hợp đồng & tạm ứng'],['Thi công phần móng',15,'Nghiệm thu móng'],['Thi công phần thô',20,'Nghiệm thu kết cấu thô'],['Thi công MEP',15,'Nghiệm thu hệ thống MEP'],['Thi công hoàn thiện',20,'Nghiệm thu hoàn thiện'],['Lắp đặt thiết bị',10,'Nghiệm thu thiết bị'],['Nghiệm thu tổng thể',5,'Bàn giao'],['Giữ lại bảo hành',5,'Sau thời hạn bảo hành']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}%</td><td>${BMH.money(e.total*r[1]/100)}</td><td>${r[2]}</td></tr>`).join('')}<tr class="total"><td>Tổng cộng</td><td>100%</td><td>${BMH.money(e.total)}</td><td>—</td></tr></tbody></table></div></section><section class="card handover-check"><h2>Bàn giao công trình</h2>${['Hồ sơ hoàn công','Danh sách vật liệu đã dùng','Bảo hành','Thiết bị điện nước','Hướng dẫn vận hành','Hình ảnh nghiệm thu'].map(x=>`<span>✓ <b>${x}</b></span>`).join('')}<div class="info-strip green">✓ Tất cả tài liệu đã được tập hợp. Hãy kiểm tra pháp lý và nghiệm thu thực tế trước khi ký bàn giao.</div></section></div></section><aside class="handover-side"><div class="card completion"><i>✓</i><div><h2>Hoàn thành hành trình!</h2><p>Ngôi nhà mơ ước của bạn đã sẵn sàng bước sang giai đoạn triển khai thực tế.</p></div></div><div class="card finance-summary"><h2>Tổng quan tài chính</h2><dl><div><dt>Tổng chi phí</dt><dd>${BMH.money(e.total)}</dd></div><div><dt>Dự phòng còn lại</dt><dd>${BMH.money(Math.max(0,e.gap))}</dd></div><div><dt>Bảo hành giữ lại 5%</dt><dd>${BMH.money(e.total*.05)}</dd></div></dl><h3>Trạng thái dự án <span>Sẵn sàng bàn giao</span></h3><p>Dữ liệu dự án đã được tổng hợp và có thể tải xuống để tiếp tục làm việc với kiến trúc sư, kỹ sư và nhà thầu.</p><button class="clay" data-export="bundle">${BMH.icon('download')} Tải trọn bộ hồ sơ</button><button class="secondary" data-print>Xuất báo cáo cuối cùng</button></div></aside></div>`};

BMH.lockedScreen = step => `${BMH.hero(step,step===9?'Giám sát thi công':'Hồ sơ bàn giao','đang khóa','Quyền truy cập premium được khóa chung và chỉ mở sau khi thanh toán được xác nhận.',{banner:false})}<section class="locked-panel"><div>🔒</div><h2>Bước ${step} đang khóa</h2><p>Vui lòng hoàn tất thanh toán 99.000đ tại Bước 8 để mở khóa checklist, giám sát và hồ sơ bàn giao.</p><button class="clay" data-nav="8">Quay về Bước 8</button></section>`;
BMH.SCREENS=[BMH.screen1,BMH.screen2,BMH.screen3,BMH.screen4,BMH.screen5,BMH.screen6,BMH.screen7,BMH.screen8,BMH.screen9,BMH.screen10];
